file.content:
    if replay["tip"] != checkpoint["tip"]:
        raise _CheckpointError(ERR_STATE)
    if replay["verified_tx_ids"] != context["verified_tx_ids"]:
        raise _CheckpointError(ERR_STATE)


def _validate_checkpoint_shape(data: object) -> dict:
    """Validate the exact key order and JSON types of one checkpoint document."""
    if not isinstance(data, dict) or tuple(data.keys()) != CHECKPOINT_KEYS:
        raise _CheckpointError(ERR_STATE)
    generation = data["generation"]
    anchor = data["anchor"]
    tip = data["tip"]
    context = data["context"]
    state_hash = data["state_hash"]

    if not _is_int(generation) or generation < 1:
        raise _CheckpointError(ERR_STATE)
    if not isinstance(anchor, dict):
        raise _CheckpointError(ERR_STATE)
    if not isinstance(tip, dict):
        raise _CheckpointError(ERR_STATE)
    if not isinstance(context, dict) or tuple(context.keys()) != CHECKPOINT_CONTEXT_KEYS:
        raise _CheckpointError(ERR_STATE)
    if not crypto.is_hex64(state_hash):
        raise _CheckpointError(ERR_STATE)

    verified_at = context["verified_at"]
    trust = context["trust"]
    documents = context["documents"]
    verified_tx_ids = context["verified_tx_ids"]
    if not _is_int(verified_at) or verified_at < 0:
        raise _CheckpointError(ERR_STATE)
    if not isinstance(trust, dict):
        raise _CheckpointError(ERR_STATE)
    if not isinstance(documents, list) or not documents:
        raise _CheckpointError(ERR_STATE)
    if not isinstance(verified_tx_ids, list) or any(
        not isinstance(tx_id, str) for tx_id in verified_tx_ids
    ):
        raise _CheckpointError(ERR_STATE)

    # The anchor and tip are additionally shape-checked so a corrupt document
    # can never reach the replay (which treats them as trusted call arguments).
    if _validate_advance_anchor(anchor) is None:
        raise _CheckpointError(ERR_STATE)
    if set(tip) != set(DESCRIPTOR_FIELDS):
        raise _CheckpointError(ERR_STATE)
    if not _is_int(tip.get("height")) or tip["height"] < 0:
        raise _CheckpointError(ERR_STATE)
    if not _is_int(tip.get("length")) or tip["length"] < 1:
        raise _CheckpointError(ERR_STATE)
    if not crypto.is_hex64(tip.get("tip_hash")):
        raise _CheckpointError(ERR_STATE)
    if tip.get("status") not in (STATUS_CONFIRMED, STATUS_PENDING):
        raise _CheckpointError(ERR_STATE)

    return {
        "generation": generation,
        "anchor": anchor,
        "tip": tip,
        "context": context,
        "state_hash": state_hash,
    }


def _serialize_document(ordered: dict) -> bytes:
    """Compact UTF-8 JSON (non-ASCII unescaped) with one trailing newline."""
    return (
        json.dumps(ordered, ensure_ascii=False, separators=(",", ":")) + "\n"
    ).encode("utf-8")


def _atomic_write_checkpoint(path: str, checkpoint: dict) -> None:
    """Write the checkpoint in declared key order and atomically replace ``path``."""
    ordered = {key: checkpoint[key] for key in CHECKPOINT_KEYS}
    _atomic_write_bytes(path, _serialize_document(ordered))


def _atomic_write_bytes(path: str, payload: bytes) -> None:
    """Atomically replace ``path`` with ``payload``.

    The temp file is fsynced before the replace and the directory afterwards,
    mirroring the main store's durability rules.
    """
    directory = os.path.dirname(os.path.abspath(path)) or "."
    os.makedirs(directory, exist_ok=True)
    fd, tmp_path = tempfile.mkstemp(prefix=".light-checkpoint-", dir=directory)
    promoted = False
    try:
        with os.fdopen(fd, "wb") as fh:
            fh.write(payload)
            fh.flush()
            os.fsync(fh.fileno())
        os.replace(tmp_path, path)
        promoted = True
        _fsync_dir(directory)
    finally:
        if not promoted and os.path.exists(tmp_path):
            try:
                os.unlink(tmp_path)
            except OSError:
                pass


def _read_bytes_or_none(path: str) -> bytes | None:
    """Raw bytes of ``path`` (None when absent); other read errors propagate."""
    try:
        with open(path, "rb") as fh:
            return fh.read()
    except FileNotFoundError:
        return None


def _restore_bytes(path: str, original: bytes | None) -> None:
    """Best-effort compensation: put ``original`` back at ``path``.

    A file that did not exist is unlinked again. Any failure is swallowed —
    the caller already reports ``io`` and the next strict load surfaces the
    corruption as ``state``.
    """
    try:
        if original is None:
            os.unlink(path)
        else:
            _atomic_write_bytes(path, original)
    except OSError:
        pass


def _fsync_dir(directory: str) -> None:
    """Best-effort directory fsync so the checkpoint rename survives a crash."""
    try:
        dir_fd = os.open(directory, os.O_RDONLY | getattr(os, "O_DIRECTORY", 0))
    except OSError:
        return
    try:
        os.fsync(dir_fd)
    except OSError:
        pass
    finally:
        os.close(dir_fd)


# -- generation-history sidecar ------------------------------------------------


def _history_path(path: str) -> str:
    """The sidecar path mirroring one advance checkpoint path."""
    return path + ".history"


def _history_record(checkpoint: dict, prev: str) -> dict:
    """One sidecar record: ``{checkpoint, prev, hash}`` in declared key order.

    ``hash`` chains the record: SHA-256 over the ASCII bytes of ``prev``
    concatenated with the canonical (sorted, compact) JSON of the checkpoint.
    """
    ordered = {key: checkpoint[key] for key in CHECKPOINT_KEYS}
    digest = hashlib.sha256(
        prev.encode("ascii") + _canonical_json_bytes(ordered)
    ).hexdigest()
    return {"checkpoint": ordered, "prev": prev, "hash": digest}


def _atomic_write_history(path: str, document: dict) -> None:
    """Write the sidecar in declared key order and atomically replace ``path``."""
    ordered = {key: document[key] for key in HISTORY_KEYS}
    _atomic_write_bytes(path, _serialize_document(ordered))


def _load_history(path: str) -> dict | None:
    """Strictly load and replay the generation-history sidecar.

    Returns None when no file exists at ``path``. Otherwise validates the
    exact key orders and JSON types, then replays every retained generation:
    record generations must run consecutively from ``base.generation + 1``,
    each ``prev`` must name the previous record's hash (the first names
    ``base.hash``), each record hash and the head are recomputed, and every
    checkpoint passes the same state-hash/context-replay checks as
    :func:`_load_checkpoint` plus anchor continuity with its predecessor. Any
    defect is a ``state`` failure (unreadable JSON is ``state`` too, an
    unreadable file ``io``); the file is never truncated or rebuilt.
    """
    try:
        with open(path, "r", encoding="utf-8") as fh:
            text = fh.read()
    except FileNotFoundError:
        return None
    except OSError as exc:
        raise _CheckpointError(ERR_IO) from exc

    try:
        data = json.loads(text)
    except (ValueError, UnicodeDecodeError) as exc:
        raise _CheckpointError(ERR_STATE) from exc
    return _validate_history_document(data)


def _validate_history_document(data: object) -> dict:
    """Validate and replay one parsed sidecar document."""
    if not isinstance(data, dict) or tuple(data.keys()) != HISTORY_KEYS:
        raise _CheckpointError(ERR_STATE)
    if not _is_int(data["v"]) or data["v"] != HISTORY_VERSION:
        raise _CheckpointError(ERR_STATE)

    base = data["base"]
    if not isinstance(base, dict) or tuple(base.keys()) != HISTORY_BASE_KEYS:
        raise _CheckpointError(ERR_STATE)
    if not _is_int(base["generation"]) or base["generation"] < 0:
        raise _CheckpointError(ERR_STATE)
    if not crypto.is_hex64(base["hash"]):
        raise _CheckpointError(ERR_STATE)

    records = data["records"]
    if not isinstance(records, list) or not records:
        raise _CheckpointError(ERR_STATE)
    head = data["head"]
    if not crypto.is_hex64(head):
        raise _CheckpointError(ERR_STATE)

    validated = []
    prev = base["hash"]
    previous_tip: dict | None = None
    for index, raw in enumerate(records):
        record = _validate_history_record(raw)
        checkpoint = record["checkpoint"]
        if checkpoint["generation"] != base["generation"] + 1 + index:
            raise _CheckpointError(ERR_STATE)
        if record["prev"] != prev:
            raise _CheckpointError(ERR_STATE)
        if record != _history_record(checkpoint, prev):
            raise _CheckpointError(ERR_STATE)
        _verify_checkpoint_document(checkpoint)
        if previous_tip is not None:
            # Consecutive checkpoints chain: each anchor is the previous tip.
            expected_anchor = {
                "height": previous_tip["height"],
                "block_hash": previous_tip["tip_hash"],
            }
            if checkpoint["anchor"] != expected_anchor:
                raise _CheckpointError(ERR_STATE)
        previous_tip = checkpoint["tip"]
        prev = record["hash"]
        validated.append(record)

    if head != validated[-1]["hash"]:
        raise _CheckpointError(ERR_STATE)
    return {
        "v": HISTORY_VERSION,
        "base": {
            "generation": base["generation"],
            "hash": base["hash"],
        },
        "records": validated,
        "head": head,
    }


def _validate_history_record(raw: object) -> dict:
    """Validate the exact key order and JSON types of one sidecar record."""
    if not isinstance(raw, dict) or tuple(raw.keys()) != HISTORY_RECORD_KEYS:
        raise _CheckpointError(ERR_STATE)
    checkpoint = _validate_checkpoint_shape(raw["checkpoint"])
    if not crypto.is_hex64(raw["prev"]):
        raise _CheckpointError(ERR_STATE)
    if not crypto.is_hex64(raw["hash"]):
        raise _CheckpointError(ERR_STATE)
    return {"checkpoint": checkpoint, "prev": raw["prev"], "hash": raw["hash"]}


def history(path: str, generation: object = None, keep: object = None) -> dict:
    """Query or prune the generation-history sidecar of one advance checkpoint.

    ``generation`` and ``keep`` are mutually exclusive and, when given, must
    be non-boolean positive integers. Without either, the last generation's
    record is reported. With ``keep=n`` only the last ``min(n, count)``
    records are retained: when nothing is pruned the sidecar's bytes are left
    untouched, otherwise ``base`` advances to the last pruned record's
    ``{generation, hash}`` and the sidecar is rewritten under the same
    per-path lock as :func:`advance` (the checkpoint file never changes; an
    ``io`` failure restores the original bytes best-effort).

    Success returns ``{"ok", "base", "record", "head", "kept"}`` in that key
    order — ``record`` the queried (default last) or, with ``keep``, the last
    retained record, ``kept`` null for queries and the retained count for
    prunes. Failure returns ``{"ok": False, "error": category}`` with
    category one of ``input`` (bad arguments), ``io`` (the sidecar is missing
    or cannot be read/written) and ``state`` (the sidecar fails validation or
    the requested generation is not retained).
    """
    if not isinstance(path, str) or not path:
        return {"ok": False, "error": ERR_INPUT}
    if generation is not None and keep is not None:
        return {"ok": False, "error": ERR_INPUT}
    for parameter in (generation, keep):
        if parameter is not None and (not _is_int(parameter) or parameter < 1):
            return {"ok": False, "error": ERR_INPUT}

    lock = _checkpoint_lock(path)
    with lock:
        sidecar_path = _history_path(path)
        try:
            sidecar = _load_history(sidecar_path)
        except _CheckpointError as failure:
            return {"ok": False, "error": failure.category}
        if sidecar is None:
            return {"ok": False, "error": ERR_IO}

        records = sidecar["records"]
        if keep is None:
            if generation is None:
                record = records[-1]
            else:
                record = next(
                    (
                        candidate
                        for candidate in records
                        if candidate["checkpoint"]["generation"] == generation
                    ),
                    None,
                )
                if record is None:
                    return {"ok": False, "error": ERR_STATE}
            return {
                "ok": True,
                "base": sidecar["base"],
                "record": record,
                "head": sidecar["head"],
                "kept": None,
            }

        kept = min(keep, len(records))
        record = records[-1]
        if kept == len(records):
            # Nothing pruned: the sidecar's bytes stay exactly as they were.
            return {
                "ok": True,
                "base": sidecar["base"],
                "record": record,
                "head": sidecar["head"],
                "kept": kept,
            }

        last_pruned = records[len(records) - kept - 1]
        base = {
            "generation": last_pruned["checkpoint"]["generation"],
            "hash": last_pruned["hash"],
        }
        rewritten = {
            "v": HISTORY_VERSION,
            "base": base,
            "records": records[len(records) - kept :],
            "head": sidecar["head"],
        }
        try:
            original = _read_bytes_or_none(sidecar_path)
        except OSError:
            return {"ok": False, "error": ERR_IO}
        try:
            _atomic_write_history(sidecar_path, rewritten)
        except OSError:
            # Compensate: put the original bytes back best-effort.
            _restore_bytes(sidecar_path, original)
            return {"ok": False, "error": ERR_IO}
        return {
            "ok": True,
            "base": base,
            "record": record,
            "head": sidecar["head"],
            "kept": kept,
        }


# -- signed history export / offline verification -----------------------------

# The exact top-level key order of one exported history page, and of its auth.
HISTORY_PAGE_KEYS = (
    "base",
    "records",
    "next",
    "head",
    "checkpoint",
    "auth",
)
HISTORY_PAGE_AUTH_KEYS = ("public_key", "signature")

# Page-size bounds for :func:`export_history`.
HISTORY_EXPORT_MIN_LIMIT = 1
HISTORY_EXPORT_MAX_LIMIT = 200
HISTORY_EXPORT_DEFAULT_LIMIT = 50


def export_history(
    path: object,
    key: object,
    after: object = None,
    limit: object = HISTORY_EXPORT_DEFAULT_LIMIT,
    trust_path: object = None,
) -> dict:
    """Export one signed page of retained checkpoint history for offline use.

    Strictly reloads the checkpoint at ``path`` and its ``path + ".history"``
    sidecar and returns one page with the exact key order
    ``base, records, next, head, checkpoint, auth``:

    * ``base``/``records``/``head`` are the sidecar's own documents (nested
      key orders unchanged), ``checkpoint`` is the persisted five-key
      checkpoint document (identical to the last retained record's);
    * ``next`` is the last record generation of the page when another page
      follows, or ``null`` on the final page;
    * ``auth`` is ``{"public_key", "signature"}``: the Ed25519 public key
      derived from the 64-lowercase-hex seed ``key`` and its signature over the
      SHA-256 digest of the canonical (sorted, compact, non-ASCII-unescaped)
      JSON of the page with ``auth`` removed.

    ``after`` is ``None`` (page starts right after ``base``) or a non-boolean
    non-negative integer naming either ``base.generation`` or a retained
    generation that is not the last one; the page then starts at the following
    record. ``limit`` is a non-boolean integer in 1..200. Bad arguments are
    ``input``; a missing or unreadable file is ``io``; a corrupt checkpoint or
    sidecar, a sidecar/checkpoint mismatch or an unmatched/terminal cursor is
    ``state``.

    With ``trust_path`` naming a durable signer log (see
    :func:`history_trust`), the log is strictly loaded under its own per-path
    lock first (missing is ``io``; any shape/chain/certificate defect is
    ``state``) and the page is cut at authorization boundaries: it keeps the
    longest prefix, starting at the cursor, whose checkpoints all name one key
    active at their ``verified_at``, stopping just before the first record a
    single envelope key cannot cover and carrying a non-null ``next`` so the
    following export continues there (a page ending exactly at the retained
    tail still closes with ``null``). The seed ``key`` must derive to that one
    covering key; an unknown or revoked covering key — no key is active at the
    page's first record — is an ``auth`` failure. Without ``trust_path`` the
    legacy single-key behavior is unchanged.
    """
    if not isinstance(path, str) or not path:
        return {"ok": False, "error": ERR_INPUT}
    if not isinstance(key, str) or not _HEX32_RE.fullmatch(key):
        return {"ok": False, "error": ERR_INPUT}
    if after is not None and (not _is_int(after) or after < 0):
        return {"ok": False, "error": ERR_INPUT}
    if (
        not _is_int(limit)
        or limit < HISTORY_EXPORT_MIN_LIMIT
        or limit > HISTORY_EXPORT_MAX_LIMIT
    ):
        return {"ok": False, "error": ERR_INPUT}
    if trust_path is not None and (
        not isinstance(trust_path, str) or not trust_path
    ):
        return {"ok": False, "error": ERR_INPUT}
    public_key = crypto.derive_public_key(key)
    if public_key is None:
        return {"ok": False, "error": ERR_INPUT}

    lock = _checkpoint_lock(path)
    with lock:
        try:
            checkpoint = _load_checkpoint(path)
            sidecar = _load_history(_history_path(path))
        except _CheckpointError as failure:
            return {"ok": False, "error": failure.category}
        if sidecar is None:
            # Nothing retained to export: the sidecar missing is an io defect.
            return {"ok": False, "error": ERR_IO}
        if checkpoint is None:
            # A sidecar without its checkpoint is unrecoverable corruption.
            return {"ok": False, "error": ERR_STATE}

        base = sidecar["base"]
        records = sidecar["records"]
        if records[-1]["checkpoint"] != checkpoint:
            # The sidecar tip must pin the persisted checkpoint.
            return {"ok": False, "error": ERR_STATE}

        signer_entries: list[dict] | None = None
        if trust_path is not None:
            # The log has its own per-path lock, shared with history_trust
            # writers; when it names the same path it is the same reentrant
            # lock. A missing log is an io defect, a damaged one state.
            with _checkpoint_lock(trust_path):
                try:
                    signer_log = _load_signer_log(trust_path)
                except _CheckpointError as failure:
                    return {"ok": False, "error": failure.category}
            if signer_log is None:
                return {"ok": False, "error": ERR_IO}
            signer_entries = signer_log["records"]

        if after is None or after == base["generation"]:
            start = 0
        else:
            start = next(
                (
                    index + 1
                    for index, record in enumerate(records)
                    if record["checkpoint"]["generation"] == after
                ),
                None,
            )
            # An unknown cursor, or one naming the last retained generation
            # (nothing follows it), is a state defect rather than an input one:
            # the argument has a legal shape but does not name a usable cursor.
            if start is None or start >= len(records):
                return {"ok": False, "error": ERR_STATE}

        if signer_entries is None:
            page_records = records[start : start + limit]
            has_next = start + limit < len(records)
        else:
            # Keep only the maximal prefix one envelope key can sign: sample
            # the log at the first record's verified_at and stop at the first
            # record whose active key differs (a rotation or a revocation
            # window opening or closing inside the page).
            covering = _signer_active_key(
                signer_entries,
                records[start]["checkpoint"]["context"]["verified_at"],
            )
            end = start + 1
            while end < len(records) and end < start + limit:
                active = _signer_active_key(
                    signer_entries,
                    records[end]["checkpoint"]["context"]["verified_at"],
                )
                if active != covering:
                    break
                end += 1
            page_records = records[start:end]
            has_next = end < len(records)
            if covering is None or public_key != covering:
                # The page sits (or starts) in a revocation/pre-activation
                # window, or names a key the log does not authorize for it.
                return {"ok": False, "error": ERR_AUTH}

        next_value = (
            page_records[-1]["checkpoint"]["generation"] if has_next else None
        )
        page = {
            "base": base,
            "records": page_records,
            "next": next_value,
            "head": sidecar["head"],
            "checkpoint": checkpoint,
        }
        digest = hashlib.sha256(_canonical_json_bytes(page)).digest()
        signature = crypto.sign_message(key, digest)
        if signature is None:
            return {"ok": False, "error": ERR_INPUT}
        page["auth"] = {"public_key": public_key, "signature": signature}
        return {name: page[name] for name in HISTORY_PAGE_KEYS}


def verify_history(pages: object, public_key: object) -> dict:
    """Verify an ordered, non-empty batch of signed history pages offline.

    Every page must have the exact key order
    ``base, records, next, head, checkpoint, auth`` (nested documents keep
    their declared orders and types) and carry
    ``auth = {"public_key", "signature"}``. The pinned ``public_key`` (64
    lowercase hex) must match every page's signing key and verify every
    Ed25519 signature over the auth-less canonical page digest; ``base``,
    ``head`` and the page ``checkpoint`` must be identical across all pages.

    Records must run consecutively from ``base.generation + 1`` with each
    ``prev``/``hash`` link recomputed, chaining across page seams in step with
    each non-final page's ``next`` cursor; every checkpoint is replayed (state
    hash plus its stored batch context) with anchor continuity between
    consecutive checkpoints. Only the final page may carry ``next: null``; its
    last record's hash must equal ``head`` and its checkpoint must equal the
    page checkpoint. Missing, duplicate or reordered pages and any tampering
    are rejected.

    Returns ``{"ok": True}`` on success or ``{"ok": False, "error":
    category}`` on failure with category one of ``input`` (structure/types),
    ``auth`` (pinned key or a failing signature) and ``integrity`` (chaining,
    pagination or checkpoint replay). Never raises for malformed input.
    """
    try:
        if not isinstance(public_key, str) or not _HEX32_RE.fullmatch(public_key):
            raise _Failure(ERR_INPUT)
        parsed = _parse_all_history_pages(pages)

        def authenticate(page: dict, check_shared: object) -> None:
            # The old verifier judges the pinned-key mismatch before the
            # shared-field comparison and the signature afterwards, so a page
            # failing both reports ``auth`` for the key (and, only once the
            # shared envelope matches, a bad signature).
            if page["auth"]["public_key"] != public_key:
                raise _Failure(ERR_AUTH)
            check_shared()
            _verify_history_page_signature(page, public_key)

        _run_history_checks(parsed, authenticate)
    except _Failure as failure:
        return {"ok": False, "error": failure.category}
    except Exception:
        # Defensive: structurally unforeseeable inputs must report rather than
        # crash the verifying process.
        return {"ok": False, "error": ERR_INPUT}
    return {"ok": True}


def _validate_page_base(raw: object) -> dict:
    """Validate one exported page's ``{generation, hash}`` base document."""
    if not isinstance(raw, dict) or tuple(raw.keys()) != HISTORY_BASE_KEYS:
        raise _Failure(ERR_INPUT)
    if not _is_int(raw["generation"]) or raw["generation"] < 0:
        raise _Failure(ERR_INPUT)
    if not crypto.is_hex64(raw["hash"]):
        raise _Failure(ERR_INPUT)
    return {"generation": raw["generation"], "hash": raw["hash"]}


def _validate_page_checkpoint(raw: object) -> dict:
    """Shape-validate a checkpoint embedded in an exported history page.

    Shape/type defects are the page's structural defects (``input``); the
    state hash and context replay are judged separately as ``integrity``.
    """
    try:
        return _validate_checkpoint_shape(raw)
    except _CheckpointError:
        raise _Failure(ERR_INPUT) from None


def _validate_page_record(raw: object) -> dict:
    """Validate one ``{checkpoint, prev, hash}`` record embedded in a page."""
    if not isinstance(raw, dict) or tuple(raw.keys()) != HISTORY_RECORD_KEYS:
        raise _Failure(ERR_INPUT)
    checkpoint = _validate_page_checkpoint(raw["checkpoint"])
    if not crypto.is_hex64(raw["prev"]) or not crypto.is_hex64(raw["hash"]):
        raise _Failure(ERR_INPUT)
    return {"checkpoint": checkpoint, "prev": raw["prev"], "hash": raw["hash"]}


def _parse_history_page(raw_page: object) -> dict:
    """Shape-validate one exported history page.

    Returns ``{"raw", "auth", "base", "head", "checkpoint", "records",
    "next"}`` with every nested document's key order and JSON type already
    validated. Raises :class:`_Failure` (``input``) on every structural
    defect; never judges signatures or cross-page chaining.
    """
    if not isinstance(raw_page, dict) or tuple(raw_page.keys()) != HISTORY_PAGE_KEYS:
        raise _Failure(ERR_INPUT)
    auth = raw_page["auth"]
    if not isinstance(auth, dict) or tuple(auth.keys()) != HISTORY_PAGE_AUTH_KEYS:
        raise _Failure(ERR_INPUT)
    if not crypto.is_hex64(auth["public_key"]):
        raise _Failure(ERR_INPUT)
    if not crypto.is_hex128(auth["signature"]):
        raise _Failure(ERR_INPUT)
    base = _validate_page_base(raw_page["base"])
    head = raw_page["head"]
    if not crypto.is_hex64(head):
        raise _Failure(ERR_INPUT)
    page_checkpoint = _validate_page_checkpoint(raw_page["checkpoint"])
    records = raw_page["records"]
    if not isinstance(records, list) or not records:
        raise _Failure(ERR_INPUT)
    next_value = raw_page["next"]
    if next_value is not None and (not _is_int(next_value) or next_value < 0):
        raise _Failure(ERR_INPUT)
    # Every embedded record is shape- and type-validated up front, so a
    # structurally malformed page reports ``input`` even if its (now
    # mismatched) signature would fail too — structure precedes trust.
    validated_records = [_validate_page_record(raw) for raw in records]
    return {
        "raw": raw_page,
        "auth": auth,
        "base": base,
        "head": head,
        "checkpoint": page_checkpoint,
        "records": validated_records,
        "next": next_value,
    }


def _parse_all_history_pages(pages: object) -> list[dict]:
    """Shape-validate a non-empty ordered batch of exported history pages."""
    if not isinstance(pages, list) or not pages:
        raise _Failure(ERR_INPUT)
    return [_parse_history_page(raw_page) for raw_page in pages]


def _history_page_signing_digest(raw_page: dict) -> bytes:
    """The SHA-256 digest of a page's auth-less canonical JSON document."""
    unsigned = {
        key: raw_page[key] for key in HISTORY_PAGE_KEYS if key != "auth"
    }
    return hashlib.sha256(_canonical_json_bytes(unsigned)).digest()


def _verify_history_page_signature(page: dict, signer_key: str) -> None:
    """Verify one page signature over the auth-less canonical page digest."""
    digest = _history_page_signing_digest(page["raw"])
    if not crypto.verify_signature(signer_key, digest, page["auth"]["signature"]):
        raise _Failure(ERR_AUTH)


def _run_history_checks(parsed: list[dict], authenticate: object) -> None:
    """Shared authentication/chaining core of both history verifiers.

    Pages must already be shape-validated (see
    :func:`_parse_all_history_pages`). They are processed in the exact order
    the single-key verifier always used: ``authenticate(page, check_shared)``
    runs per page (the callback invokes the deferred shared-field comparison
    at its own point relative to key/signature checks), and only then are
    that page's records generation-/prev-/hash-linked and their checkpoints
    replayed; its ``next`` cursor is checked at the page seam. After the loop
    the final page must carry ``next: null`` and close the shared
    ``head``/``checkpoint``.
    """
    common_base: dict | None = None
    common_head: str | None = None
    common_checkpoint: dict | None = None
    # Linkage state carried across page seams.
    expected_prev: str | None = None
    expected_generation: int | None = None
    previous_tip: dict | None = None

    for position, page in enumerate(parsed):
        is_last_page = position == len(parsed) - 1

        def check_shared() -> None:
            # The trust anchor (base) and signed envelope (head, checkpoint)
            # must be shared by every page of the export.
            nonlocal common_base, common_head, common_checkpoint
            if common_base is None:
                common_base = page["base"]
                common_head = page["head"]
                common_checkpoint = page["checkpoint"]
            elif page["base"] != common_base:
                raise _Failure(ERR_INTEGRITY)
            elif page["head"] != common_head or (
                page["checkpoint"] != common_checkpoint
            ):
                raise _Failure(ERR_INTEGRITY)

        authenticate(page, check_shared)

        if expected_prev is None:
            # The first page starts right at the shared base.
            expected_prev = page["base"]["hash"]
            expected_generation = page["base"]["generation"] + 1

        for record in page["records"]:
            checkpoint = record["checkpoint"]
            if checkpoint["generation"] != expected_generation:
                # A gap, duplicate or reordered page breaks generation order.
                raise _Failure(ERR_INTEGRITY)
            if record["prev"] != expected_prev:
                raise _Failure(ERR_INTEGRITY)
            rebuilt = _history_record(checkpoint, expected_prev)
            if record["hash"] != rebuilt["hash"]:
                raise _Failure(ERR_INTEGRITY)
            # The state hash pins the document; the stored batch must replay
            # from its anchor to its tip and reproduce the verified tx ids.
            try:
                _verify_checkpoint_document(checkpoint)
            except _CheckpointError:
                raise _Failure(ERR_INTEGRITY) from None
            if previous_tip is not None:
                expected_anchor = {
                    "height": previous_tip["height"],
                    "block_hash": previous_tip["tip_hash"],
                }
                if checkpoint["anchor"] != expected_anchor:
                    raise _Failure(ERR_INTEGRITY)
            previous_tip = checkpoint["tip"]
            expected_prev = record["hash"]
            expected_generation += 1

        last_generation = page["records"][-1]["checkpoint"]["generation"]
        if is_last_page:
            if page["next"] is not None:
                raise _Failure(ERR_INTEGRITY)
        else:
            # A non-final page must name its last record as the cursor the
            # next page continues from.
            if page["next"] != last_generation:
                raise _Failure(ERR_INTEGRITY)

    # The final page closes the export: its last record is the sidecar head
    # and its checkpoint is the page checkpoint shared by every page.
    final_record = parsed[-1]["records"][-1]
    if final_record["hash"] != common_head:
        raise _Failure(ERR_INTEGRITY)
    if final_record["checkpoint"] != common_checkpoint:
        raise _Failure(ERR_INTEGRITY)


# -- signed history export verification with signer rotation/revocation --------

# The exact top-level key order of one signer trust/rotation log, and the exact
# key order of one record in it.
HISTORY_TRUST_KEYS = ("root", "records", "head")
SIGNER_RECORD_KEYS = ("at", "key", "status", "prev", "signature")
SIGNER_STATUSES = ("active", "revoked")

# The first signer record's ``prev`` names no predecessor (64 zeros).
SIGNER_ZERO_HASH = "0" * 64


def verify_history_trust(pages: object, trust: object, root: object) -> dict:
    """Verify signed history pages against a rotating/revocable signer log.

    Same page rules as :func:`verify_history`: ``pages`` must be a non-empty
    ordered batch of pages with the exact key order
    ``base, records, next, head, checkpoint, auth`` and valid nested documents,
    shared ``base``/``head``/``checkpoint``, consecutive record generations,
    recomputed ``prev``/``hash`` links, ``next`` cursor seams, replayed
    checkpoints with anchor continuity and final-page closure — but each page's
    ``auth.public_key`` may name a different signer.

    ``trust`` is a signer log with the exact key order ``root, records, head``:

    * ``root`` is a 64-lowercase-hex Ed25519 key and must equal the pinned
      ``root`` argument;
    * ``records`` is a non-empty list of items with the exact key order
      ``at, key, status, prev, signature``: ``at`` a plain (non-boolean)
      positive integer running strictly ascending, ``key``/``prev`` 64
      lowercase hex, ``status`` exactly ``active`` or ``revoked`` and
      ``signature`` 128 lowercase hex;
    * the first item's ``prev`` is 64 zeros and every later one is the
      SHA-256 of the previous item's canonical (sorted, compact) JSON; ``head``
      is the same hash of the final item;
    * every ``signature`` is the root key's Ed25519 signature over the
      SHA-256 of the item's canonical JSON with ``signature`` removed.

    An ``active`` item authorizes ``key`` from its ``at`` until the following
    item; a ``revoked`` item withdraws the key from its ``at`` until a later
    ``active`` item. A page is accepted only when one single key is active for
    every checkpoint ``verified_at`` it carries (a page spanning an
    authorization boundary is rejected), the page names that key and its
    signature verifies over the auth-less canonical page digest.

    Returns ``{"ok": True}`` on success or ``{"ok": False, "error":
    category}`` on failure: ``input`` (missing/extra/reordered keys, wrong
    types or hex), ``auth`` (root mismatch, a bad certificate or page
    signature, an unknown or revoked page key) and ``integrity`` (``at`` not
    ascending, a bad ``prev``/``head``, an authorization-boundary crossing, or
    any record/pagination/checkpoint-replay defect). Never raises.
    """
    try:
        if not isinstance(root, str) or not _HEX32_RE.fullmatch(root):
            raise _Failure(ERR_INPUT)
        parsed = _parse_all_history_pages(pages)
        entries, head, trust_root = _parse_signer_trust(trust)
        # All structural checks precede trust: the well-formed log root is
        # bound to the pinned argument only after every record has a legal
        # shape and a strictly ascending ``at`` sequence.
        if trust_root != root:
            raise _Failure(ERR_AUTH)
        _check_signer_log_chains(entries, head)
        _verify_signer_certificates(entries, root)

        def authenticate(page: dict, check_shared: object) -> None:
            # Resolve the one key the log authorizes for this page's whole
            # span before the shared-envelope comparison and signature check,
            # mirroring the single-key verifier's auth-before-shared order.
            authorized = _page_authorized_key(page, entries)
            check_shared()
            _verify_history_page_signature(page, authorized)

        _run_history_checks(parsed, authenticate)
    except _Failure as failure:
        return {"ok": False, "error": failure.category}
    except Exception:
        # Defensive: structurally unforeseeable inputs must report rather than
        # crash the verifying process.
        return {"ok": False, "error": ERR_INPUT}
    return {"ok": True}


def _parse_signer_trust(trust: object) -> tuple[list[dict], str, str]:
    """Shape-validate the signer rotation log.

    Returns ``(entries, head, root)`` with every item already carrying the
    right keys, types and hex. Key-order/type/hex defects are ``input``; the
    caller binds the well-formed ``root`` to its pinned argument (``auth``)
    before the strictly-ascending ``at`` order, ``prev``/``head`` links
    (``integrity``) and certificate signatures (``auth``) are judged.
    """
    if not isinstance(trust, dict) or tuple(trust.keys()) != HISTORY_TRUST_KEYS:
        raise _Failure(ERR_INPUT)
    trust_root = trust["root"]
    if not crypto.is_hex64(trust_root):
        raise _Failure(ERR_INPUT)
    records = trust["records"]
    if not isinstance(records, list) or not records:
        raise _Failure(ERR_INPUT)
    entries: list[dict] = []
    for raw in records:
        if not isinstance(raw, dict) or tuple(raw.keys()) != SIGNER_RECORD_KEYS:
            raise _Failure(ERR_INPUT)
        at_value = raw["at"]
        key = raw["key"]
        status = raw["status"]
        prev = raw["prev"]
        signature = raw["signature"]
        # Booleans are rejected even though they are integers; every ``at`` is
        # a positive instant.
        if not _is_int(at_value) or at_value < 1:
            raise _Failure(ERR_INPUT)
        if not crypto.is_hex64(key) or not crypto.is_hex64(prev):
            raise _Failure(ERR_INPUT)
        if status not in SIGNER_STATUSES:
            raise _Failure(ERR_INPUT)
        if not crypto.is_hex128(signature):
            raise _Failure(ERR_INPUT)
        entries.append(
            {
                "raw": raw,
                "at": at_value,
                "key": key,
                "status": status,
                "prev": prev,
                "signature": signature,
            }
        )
    head = trust["head"]
    if not crypto.is_hex64(head):
        raise _Failure(ERR_INPUT)
    return entries, head, trust_root


def _signer_record_hash(raw: dict) -> str:
    """SHA-256 of one signer record's full canonical (sorted, compact) JSON."""
    return hashlib.sha256(_canonical_json_bytes(raw)).hexdigest()


def _check_signer_log_chains(entries: list[dict], head: str) -> None:
    """Check strictly ascending ``at`` values, ``prev`` links and ``head``."""
    # The strictly ascending ``at`` sequence is a log-ordering rule rather
    # than a shape rule, so a repeat or decrease is an integrity failure.
    for earlier, later in zip(entries, entries[1:]):
        if later["at"] <= earlier["at"]:
            raise _Failure(ERR_INTEGRITY)
    expected_prev = SIGNER_ZERO_HASH
    for entry in entries:
        if entry["prev"] != expected_prev:
            raise _Failure(ERR_INTEGRITY)
        expected_prev = _signer_record_hash(entry["raw"])
    if head != expected_prev:
        raise _Failure(ERR_INTEGRITY)


def _signer_active_key(entries: list[dict], instant: int) -> str | None:
    """The key authorized at ``instant`` per the last item with ``at <= instant``.

    ``active`` authorizes that item's key from its ``at`` until the next item;
    ``revoked`` withdraws it until a later ``active`` item. Returns None when
    no item precedes ``instant`` or the latest one revokes.
    """
    current: str | None = None
    for entry in entries:
        if entry["at"] > instant:
            break
        if entry["status"] == "active":
            current = entry["key"]
        else:
            current = None
    return current


def _page_authorized_key(page: dict, entries: list[dict]) -> str:
    """Resolve the single key the log authorizes for one page's whole span.

    The log's active key is sampled at every checkpoint ``verified_at`` the
    page carries. All samples must agree: a page straddling any
    authorization boundary — a rotation to another key or a transition into
    (or out of) a revocation window — cannot carry one envelope signature
    valid for all its generations and is an integrity failure. When no key
    is active anywhere on the page (before the first activation or inside a
    revocation window), or the page names another key, that is an unknown or
    revoked signer: an auth failure. Returns the key the signature must be
    checked against.
    """
    times = [
        record["checkpoint"]["context"]["verified_at"]
        for record in page["records"]
    ]
    authorized: str | None = _signer_active_key(entries, times[0])
    for instant in times[1:]:
        if _signer_active_key(entries, instant) != authorized:
            # The page straddles a rotation/revocation boundary, so no single
            # envelope key can have signed all its checkpoints.
            raise _Failure(ERR_INTEGRITY)
    if authorized is None:
        # Every checkpoint sits outside an active window: the page's key is
        # unknown or revoked for its whole span.
        raise _Failure(ERR_AUTH)
    if page["auth"]["public_key"] != authorized:
        raise _Failure(ERR_AUTH)
    return authorized


def _verify_signer_certificates(entries: list[dict], root: str) -> None:
    """Verify every signer record's root signature over its unsigned body."""
    for entry in entries:
        unsigned = {
            key: entry["raw"][key]
            for key in SIGNER_RECORD_KEYS
            if key != "signature"
        }
        digest = hashlib.sha256(_canonical_json_bytes(unsigned)).digest()
        if not crypto.verify_signature(root, digest, entry["signature"]):
            raise _Failure(ERR_AUTH)


# -- durable signer trust log --------------------------------------------------


def _load_signer_log(path: str) -> dict | None:
    """Strictly load and verify the durable signer log at ``path``.

    Returns None when no file exists. Otherwise the document is parsed with
    the exact :func:`verify_history_trust` rules — top-level/record key order
    and types (``input`` there), strictly ascending ``at`` and ``prev``/
    ``head`` links (``integrity`` there) and every root certificate signature
    (``auth`` there) — but every defect of a *persisted* log is reported as
    ``state`` corruption, never as a verifier category. An unreadable file is
    an ``io`` failure.
    """
    try:
        with open(path, "r", encoding="utf-8") as fh:
            text = fh.read()
    except FileNotFoundError:
        return None
    except OSError as exc:
        raise _CheckpointError(ERR_IO) from exc

    try:
        data = json.loads(text)
    except (ValueError, UnicodeDecodeError) as exc:
        raise _CheckpointError(ERR_STATE) from exc
    try:
        entries, head, root = _parse_signer_trust(data)
        _check_signer_log_chains(entries, head)
        _verify_signer_certificates(entries, root)
    except _Failure:
        raise _CheckpointError(ERR_STATE) from None
    return {
        "root": root,
        "records": [entry["raw"] for entry in entries],
        "head": head,
    }


def _atomic_write_signer_log(path: str, document: dict) -> None:
    """Write the signer log in declared key order and atomically replace."""
    ordered = {
        "root": document["root"],
        "records": [
            {key: record[key] for key in SIGNER_RECORD_KEYS}
            for record in document["records"]
        ],
        "head": document["head"],
    }
    _atomic_write_bytes(path, _serialize_document(ordered))


def history_trust(
    path: object,
    root_seed: object = None,
    at: object = None,
    key: object = None,
    status: object = None,
) -> dict:
    """Read or append one entry of the durable checkpoint-history signer log.

    The log file follows the exact :func:`verify_history_trust` document
    contract: key order ``root, records, head``, records
    ``at, key, status, prev, signature`` with 64-zero-anchored canonical-hash
    links and root-signed certificates, serialized as compact UTF-8 JSON
    (non-ASCII unescaped) with one trailing newline and atomically replaced
    under the per-path lock shared with every other same-``path`` operation.

    With only ``path`` given, the log is strictly loaded and returned in its
    declared key order. An update requires all four of ``root_seed`` (a
    64-lowercase-hex Ed25519 seed whose public key is the log root), ``at`` (a
    plain non-boolean positive integer), ``key`` (the 64-lowercase-hex public
    key the entry names) and ``status`` (``active``/``revoked``). Append
    rules: a fresh log's first entry must be ``active``; ``at`` must strictly
    exceed the last entry's; a ``revoked`` entry must name the key currently
    active (the last item with a smaller ``at``); an entry byte-identical in
    ``at``/``key``/``status`` to the current last one is an idempotent no-op.

    Success returns the ``{root, records, head}`` document. Failure is
    ``{"ok": False, "error": category}`` with category one of ``input``
    (argument shape), ``auth`` (the seed's root does not match the existing
    log), ``state`` (a corrupt or conflicting log) and ``io`` (the log is
    missing on read or cannot be read/written; a failed write restores the
    original bytes best-effort).
    """
    if not isinstance(path, str) or not path:
        return {"ok": False, "error": ERR_INPUT}
    options = (root_seed, at, key, status)
    given = [value is not None for value in options]
    if any(given) and not all(given):
        # An update needs all four fields; a partial option set never names a
        # well-formed certificate.
        return {"ok": False, "error": ERR_INPUT}
    updating = any(given)

    root_pub: str | None = None
    if updating:
        if not isinstance(root_seed, str) or not _HEX32_RE.fullmatch(root_seed):
            return {"ok": False, "error": ERR_INPUT}
        if not isinstance(key, str) or not crypto.is_hex64(key):
            return {"ok": False, "error": ERR_INPUT}
        if not _is_int(at) or at < 1:
            return {"ok": False, "error": ERR_INPUT}
        if status not in SIGNER_STATUSES:
            return {"ok": False, "error": ERR_INPUT}
        root_pub = crypto.derive_public_key(root_seed)
        if root_pub is None:
            return {"ok": False, "error": ERR_INPUT}

    lock = _checkpoint_lock(path)
    with lock:
        try:
            log = _load_signer_log(path)
        except _CheckpointError as failure:
            return {"ok": False, "error": failure.category}

        if not updating:
            if log is None:
                # Reading a log that does not exist is an io defect.
                return {"ok": False, "error": ERR_IO}
            return log

        assert root_pub is not None
        if log is None:
            # A fresh log starts with its first activation; anything else
            # (including an opening revocation) is a state conflict.
            if status != "active":
                return {"ok": False, "error": ERR_STATE}
            records: list[dict] = []
            prev = SIGNER_ZERO_HASH
        else:
            if log["root"] != root_pub:
                # Entries can only be certified by the log's own root key.
                return {"ok": False, "error": ERR_AUTH}
            records = log["records"]
            last_record = records[-1]
            if (
                last_record["at"] == at
                and last_record["key"] == key
                and last_record["status"] == status
            ):
                # Same certificate replayed against the tail: idempotent, the
                # file bytes stay exactly as they were.
                return log
            if at <= last_record["at"]:
                # The log is append-only with a strictly ascending clock.
                return {"ok": False, "error": ERR_STATE}
            if status == "revoked":
                # Only the key currently authorized may be withdrawn. Every
                # existing item precedes the new strictly-larger ``at``.
                current = _signer_active_key(records, at)
                if current is None or current != key:
                    return {"ok": False, "error": ERR_STATE}
            prev = log["head"]

        unsigned = {"at": at, "key": key, "status": status, "prev": prev}
        digest = hashlib.sha256(_canonical_json_bytes(unsigned)).digest()
        signature = crypto.sign_message(root_seed, digest)
        if signature is None:
            return {"ok": False, "error": ERR_INPUT}
        record = dict(unsigned)
        record["signature"] = signature
        written = {
            "root": root_pub,
            "records": records + [record],
            "head": _signer_record_hash(record),
        }

        try:
            original = _read_bytes_or_none(path)
        except OSError:
            return {"ok": False, "error": ERR_IO}
        try:
            _atomic_write_signer_log(path, written)
        except OSError:
            # Compensate: put the original bytes back best-effort.
            _restore_bytes(path, original)
            return {"ok": False, "error": ERR_IO}
        return written

"""HTTP server exposing the ledger REST API using the Python standard library."""
from __future__ import annotations

import json
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import parse_qs, unquote

from .service import LedgerService

MAX_BODY_BYTES = 1 << 20  # 1 MiB cap on request bodies


def build_handler(service: LedgerService) -> type[BaseHTTPRequestHandler]:
    """Create a handler class closed over the given ledger service."""

    class LedgerHandler(BaseHTTPRequestHandler):
        server_version = "VerifiableLedger/1.0"

        # -- helpers --------------------------------------------------------

        def _send_json(
            self, status: int, body: dict, sort_keys: bool = True
        ) -> None:
            data = json.dumps(
                body, ensure_ascii=False, sort_keys=sort_keys
            ).encode("utf-8")
            self.send_response(status)
            self.send_header("Content-Type", "application/json; charset=utf-8")
            self.send_header("Content-Length", str(len(data)))
            self.end_headers()
            self.wfile.write(data)

        def _read_json(self) -> tuple[bool, object]:
            try:
                length = int(self.headers.get("Content-Length", "0"))
            except ValueError:
                return False, {"error": "invalid Content-Length"}
            if length <= 0:
                return False, {"error": "request body must be JSON"}
            if length > MAX_BODY_BYTES:
                return False, {"error": "request body too large"}
            raw = self.rfile.read(length)
            try:
                return True, json.loads(raw.decode("utf-8"))
            except (ValueError, UnicodeDecodeError):
                return False, {"error": "request body must be valid JSON"}

        # -- routing --------------------------------------------------------

        def do_POST(self) -> None:  # noqa: N802 (stdlib naming)
            path = self.path.split("?", 1)[0]
            if path == "/v1/transactions":
                ok, payload = self._read_json()
                if not ok:
                    self._send_json(400, payload)  # type: ignore[arg-type]
                    return
                status, body = service.submit_transaction(payload)
                self._send_json(status, body)
            elif path == "/v1/forks/candidates":
                ok, payload = self._read_json()
                if not ok:
                    self._send_json(400, payload)  # type: ignore[arg-type]
                    return
                status, body = service.submit_fork_candidate(payload)
                self._send_json(status, body)
            elif path == "/v1/forks/sync/range":
                ok, payload = self._read_json()
                if not ok:
                    self._send_json(400, payload)  # type: ignore[arg-type]
                    return
                status, body = service.submit_fork_sync_range(payload)
                self._send_json(status, body)
            elif path == "/v1/forks/sync/range/attested":
                ok, payload = self._read_json()
                if not ok:
                    self._send_json(400, payload)  # type: ignore[arg-type]
                    return
                status, body = service.submit_fork_sync_range_attested(payload)
                self._send_json(status, body)
            elif path == "/v1/forks/sync/attested":
                ok, payload = self._read_json()
                if not ok:
                    self._send_json(400, payload)  # type: ignore[arg-type]
                    return
                status, body = service.submit_fork_sync_attested(payload)
                self._send_json(status, body)
            elif path == "/v1/forks/sync":
                ok, payload = self._read_json()
                if not ok:
                    self._send_json(400, payload)  # type: ignore[arg-type]
                    return
                status, body = service.submit_fork_sync(payload)
                self._send_json(status, body)
            elif path == "/v1/audit/signer/rotate":
                # POST /v1/audit/signer/rotate — rotate the Ed25519 key that
                # authenticates audit export checkpoints.
                ok, payload = self._read_json()
                if not ok:
                    self._send_json(400, payload)  # type: ignore[arg-type]
                    return
                status, body = service.rotate_audit_signer(payload)
                self._send_json(status, body)
            elif path == "/v1/trust/sources":
                # POST /v1/trust/sources — register a trusted source.
                ok, payload = self._read_json()
                if not ok:
                    self._send_json(400, payload)  # type: ignore[arg-type]
                    return
                status, body = service.register_trust_source(payload)
                self._send_json(status, body)
            elif (
                path.startswith("/v1/trust/sources/")
                and (path.endswith("/rotate") or path.endswith("/revoke"))
            ):
                # POST /v1/trust/sources/{source}/rotate | /revoke
                ok, payload = self._read_json()
                if not ok:
                    self._send_json(400, payload)  # type: ignore[arg-type]
                    return
                remainder = path[len("/v1/trust/sources/") :]
                if remainder.endswith("/rotate"):
                    source = unquote(remainder[: -len("/rotate")])
                    status, body = service.rotate_trust_source(source, payload)
                else:
                    source = unquote(remainder[: -len("/revoke")])
                    status, body = service.revoke_trust_source(source, payload)
                self._send_json(status, body)
            elif path == "/v1/trust/allowlist":
                # POST /v1/trust/allowlist — add a keyless offline-verify entry.
                ok, payload = self._read_json()
                if not ok:
                    self._send_json(400, payload)  # type: ignore[arg-type]
                    return
                status, body = service.add_allowlist_entry(payload)
                self._send_json(status, body)
            elif path.startswith("/v1/forks/") and path.endswith("/adopt"):
                # POST /v1/forks/{tip_hash}/adopt — a body is not required.
                if self.headers.get("Content-Length"):
                    self._read_json()
                tip_hash = unquote(path[len("/v1/forks/") : -len("/adopt")])
                status, body = service.adopt_fork(tip_hash)
                self._send_json(status, body)
            elif path == "/v1/blocks":
                # A body is not required; drain one if present.
                if self.headers.get("Content-Length"):
                    self._read_json()
                status, body = service.mine_block()
                self._send_json(status, body)
            elif path.startswith("/v1/blocks/"):
                remainder = path[len("/v1/blocks/") :]
                if remainder.endswith("/proofs"):
                    # POST /v1/blocks/{height}/proofs — batch Merkle proofs.
                    # The body is {"tx_ids": [...]} and is strictly validated
                    # by the service (400), before any state is read. The
                    # success document has a contract-fixed key order
                    # (height, block_hash, merkle_root, transaction_ids,
                    # proofs), so it is serialized in insertion order rather
                    # than alphabetically.
                    height = unquote(remainder[: -len("/proofs")])
                    ok, payload = self._read_json()
                    if not ok:
                        self._send_json(400, payload)  # type: ignore[arg-type]
                        return
                    status, body = service.get_proofs(height, payload)
                    self._send_json(status, body, sort_keys=False)
                else:
                    # POST /v1/blocks/{height}/confirm | /v1/blocks/{height}/rollback
                    if self.headers.get("Content-Length"):
                        self._read_json()
                    if remainder.endswith("/confirm"):
                        height = unquote(remainder[: -len("/confirm")])
                        status, body = service.confirm_block(height)
                    elif remainder.endswith("/rollback"):
                        height = unquote(remainder[: -len("/rollback")])
                        status, body = service.rollback_block(height)
                    else:
                        status, body = 404, {"error": "not found"}
                    self._send_json(status, body)
            else:
                self._send_json(404, {"error": "not found"})

        def do_DELETE(self) -> None:  # noqa: N802 (stdlib naming)
            path = self.path.split("?", 1)[0]
            if path.startswith("/v1/trust/allowlist/"):
                # DELETE /v1/trust/allowlist/{source}
                source = unquote(path[len("/v1/trust/allowlist/") :])
                status, body = service.remove_allowlist_entry(source)
                self._send_json(status, body)
            else:
                self._send_json(404, {"error": "not found"})

        def do_GET(self) -> None:  # noqa: N802 (stdlib naming)
            path, _, query = self.path.partition("?")
            if path.startswith("/v1/transactions/"):
                # GET /v1/transactions/{tx_id} — a transaction receipt; a
                # malformed or unknown tx_id returns 404.
                tx_id = unquote(path[len("/v1/transactions/") :])
                if not tx_id:
                    self._send_json(404, {"error": "transaction not found"})
                    return
                status, body = service.get_transaction(tx_id)
                self._send_json(status, body)
            elif path == "/v1/trust":
                # The trust document has a contract-fixed key order
                # (genesis_hash, sources, allowlist, audit_signers,
                # source_key_history), so it is serialized in insertion order
                # rather than alphabetically.
                status, body = service.get_trust_document()
                self._send_json(status, body, sort_keys=False)
            elif path == "/v1/audit/events":
                # GET /v1/audit/events?source=&kind=&cursor=&limit=
                params = {
                    key: values[0]
                    for key, values in parse_qs(query, keep_blank_values=True).items()
                }
                status, body = service.list_audit_events(params)
                self._send_json(status, body)
            elif path == "/v1/audit/export":
                # GET /v1/audit/export?cursor=&limit= — hash-anchored export
                # pages for offline audit verification. Repeated query
                # parameters are rejected 400 like the other strict endpoints.
                parsed = parse_qs(query, keep_blank_values=True)
                if any(len(values) > 1 for values in parsed.values()):
                    self._send_json(
                        400, {"error": "query parameters must not be repeated"}
                    )
                    return
                params = {key: values[0] for key, values in parsed.items()}
                status, body = service.export_audit_events(params)
                self._send_json(status, body)
            elif path == "/v1/chain/range":
                # GET /v1/chain/range?after_height=&after_hash=&limit=
                # Incremental canonical-chain page after an anchor. Repeated
                # query parameters are rejected 400 like the strict endpoints.
                parsed = parse_qs(query, keep_blank_values=True)
                if any(len(values) > 1 for values in parsed.values()):
                    self._send_json(
                        400, {"error": "query parameters must not be repeated"}
                    )
                    return
                params = {key: values[0] for key, values in parsed.items()}
                status, body = service.get_chain_range(params)
                self._send_json(status, body)
            elif path == "/v1/chain":
                status, body = service.get_chain()
                self._send_json(status, body)
            elif path.startswith("/v1/state/root/"):
                # GET /v1/state/root/{height} — account-state tree anchored at
                # a historical confirmed block; unknown/non-canonical/pending
                # heights are 404.
                height = unquote(path[len("/v1/state/root/") :])
                if not height:
                    self._send_json(404, {"error": "block not found"})
                    return
                status, body = service.get_state_root(height)
                self._send_json(status, body)
            elif path == "/v1/state/root":
                # GET /v1/state/root — confirmed account-state tree anchor.
                status, body = service.get_state_root()
                self._send_json(status, body)
            elif path == "/v1/forks/sync/export":
                # GET /v1/forks/sync/export?source=&request_id=&mode= —
                # export one received sync candidate. Repeated query
                # parameters are rejected 400 like the other strict
                # endpoints; the success document has a contract-fixed key
                # order, so it is serialized in insertion order.
                parsed = parse_qs(query, keep_blank_values=True)
                if any(len(values) > 1 for values in parsed.values()):
                    self._send_json(
                        400, {"error": "query parameters must not be repeated"}
                    )
                    return
                params = {key: values[0] for key, values in parsed.items()}
                status, body = service.export_fork_sync(params)
                self._send_json(status, body, sort_keys=False)
            elif path == "/v1/forks/sync/range/export":
                # GET /v1/forks/sync/range/export?source=&request_id=&mode= —
                # export one received incremental range delivery. Repeated
                # query parameters are rejected 400 like the other strict
                # endpoints; the success document has a contract-fixed key
                # order, so it is serialized in insertion order. This exact
                # match must precede the generic /v1/forks/{tip}/export
                # branch below.
                parsed = parse_qs(query, keep_blank_values=True)
                if any(len(values) > 1 for values in parsed.values()):
                    self._send_json(
                        400, {"error": "query parameters must not be repeated"}
                    )
                    return
                params = {key: values[0] for key, values in parsed.items()}
                status, body = service.export_fork_sync_range(params)
                self._send_json(status, body, sort_keys=False)
            elif path == "/v1/forks/sync/history":
                # GET /v1/forks/sync/history?source=&tip_hash=&kind=&
                # min_height=&max_height=&limit=&cursor=
                parsed = parse_qs(query, keep_blank_values=True)
                if any(len(values) > 1 for values in parsed.values()):
                    self._send_json(
                        400, {"error": "query parameters must not be repeated"}
                    )
                    return
                params = {key: values[0] for key, values in parsed.items()}
                status, body = service.list_fork_sync_history(params)
                self._send_json(status, body)
            elif path == "/v1/forks/sync":
                # GET /v1/forks/sync?source=&min_height=&max_height=&mode=&
                # limit=&cursor= — repeated query parameters are rejected 400
                # like the other strict endpoints.
                parsed = parse_qs(query, keep_blank_values=True)
                if any(len(values) > 1 for values in parsed.values()):
                    self._send_json(
                        400, {"error": "query parameters must not be repeated"}
                    )
                    return
                params = {key: values[0] for key, values in parsed.items()}
                status, body = service.list_fork_syncs(params)
                self._send_json(status, body)
            elif path == "/v1/index/transactions":
                # GET /v1/index/transactions?tx_id=&account=&height=&limit=&cursor=
                params = {
                    key: values[0]
                    for key, values in parse_qs(query, keep_blank_values=True).items()
                }
                status, body = service.list_transactions(params)
                self._send_json(status, body)
            elif path.startswith("/v1/forks/") and path.endswith("/export"):
                # GET /v1/forks/{tip_hash}/export
                tip_hash = unquote(path[len("/v1/forks/") : -len("/export")])
                status, body = service.export_fork(tip_hash)
                self._send_json(status, body)
            elif path.startswith("/v1/blocks/"):
                remainder = path[len("/v1/blocks/") :]
                if "/proof/" in remainder:
                    # GET /v1/blocks/{height}/proof/{tx_id}
                    height_raw, tx_raw = remainder.split("/proof/", 1)
                    if not height_raw or not tx_raw:
                        self._send_json(404, {"error": "not found"})
                        return
                    status, body = service.get_proof(unquote(height_raw), unquote(tx_raw))
                    self._send_json(status, body)
                elif remainder.endswith("/status"):
                    # GET /v1/blocks/{height}/status
                    height = unquote(remainder[: -len("/status")])
                    status, body = service.get_block_status(height)
                    self._send_json(status, body)
                else:
                    height = unquote(remainder)
                    status, body = service.get_block(height)
                    self._send_json(status, body)
            elif path.startswith("/v1/accounts/"):
                remainder = path[len("/v1/accounts/") :]
                if not remainder:
                    self._send_json(404, {"error": "account not found"})
                    return
                if remainder.endswith("/proof"):
                    # GET /v1/accounts/{account}/proof[?height=H]
                    encoded_account = remainder[: -len("/proof")]
                    account = unquote(encoded_account)
                    if not encoded_account or not account:
                        self._send_json(404, {"error": "account not found"})
                        return
                    # Repeated query parameters are rejected 400 like the other
                    # strict endpoints before the service sees them.
                    parsed = parse_qs(query, keep_blank_values=True)
                    if any(len(values) > 1 for values in parsed.values()):
                        self._send_json(
                            400, {"error": "query parameters must not be repeated"}
                        )
                        return
                    params = {key: values[0] for key, values in parsed.items()}
                    status, body = service.get_account_proof(account, params)
                else:
                    account = unquote(remainder)
                    status, body = service.get_account(account)
                self._send_json(status, body)
            else:
                self._send_json(404, {"error": "not found"})

    return LedgerHandler


def serve(service: LedgerService, host: str, port: int) -> ThreadingHTTPServer:
    """Create and run the HTTP server (blocks until interrupted)."""
    httpd = ThreadingHTTPServer((host, port), build_handler(service))
    httpd.serve_forever()
    return httpd

"""Append-only audit log hash chaining, checkpoints and offline verification.

Every audit event carries two SHA-256 links:

* ``prev_hash``  — the previous event's ``event_hash``; 64 ASCII zeroes for
  the first event;
* ``event_hash`` — ``sha256(prev_hash ASCII || canonical-event UTF-8)`` where
  the canonical event is the event with both hash fields removed, serialized
  as sorted-key compact JSON (``sort_keys=True, separators=(",", ":")``,
  non-ASCII characters emitted as raw UTF-8).

``audit_checkpoint`` is ``{"event_id", "event_hash"}`` pinning the latest
event: a fresh/empty log checks at ``{0, "0"*64}``. Offline verification walks
one or more exported pages, checking each page anchor, the dense event ids and
every link, and requires every page to pin the identical checkpoint with the
final page's last event (or the empty log) matching it.

A page may additionally carry ``checkpoint_auth`` — an Ed25519 signature over
``SHA256(sorted-compact UTF-8 JSON of {genesis_hash, checkpoint,
key_version})``. ``verify_export(document, trust)`` only checks that envelope
when a trust document (``genesis_hash`` plus a version-ascending
``audit_signers`` list) is supplied; authentication failures then use the
``auth`` error category.
"""
from __future__ import annotations

import hashlib
import json

from . import crypto

# Sentinel previous hash of the first audit event (and checkpoint of an empty
# log): 64 ASCII zeroes.
ZERO_HASH = "0" * 64

# Names of the two link fields excluded from the hashed canonical event.
HASH_FIELDS = ("prev_hash", "event_hash")

# Public offline-verification error categories.
ERR_INPUT = "input"
ERR_INTEGRITY = "integrity"
ERR_AUTH = "auth"


class AuditChainError(ValueError):
    """A persisted audit hash chain or checkpoint failed strict validation.

    Carries a human-readable ``reason``; the persistence layer maps it onto a
    ``StateRecoveryError`` tagged with the offending snapshot path.
    """

    def __init__(self, reason: str) -> None:
        self.reason = reason
        super().__init__(reason)


class _VerifyError(Exception):
    """Internal control-flow exception carrying the public error category."""

    def __init__(self, category: str) -> None:
        self.category = category
        super().__init__(category)


def _is_plain_int(value: object) -> bool:
    """Plain integer test; booleans are rejected (bool subclasses int)."""
    return isinstance(value, int) and not isinstance(value, bool)


def canonical_event(event: dict) -> bytes:
    """Sorted-key compact UTF-8 JSON of the event with both hash fields removed.

    This is the exact byte document chained into ``event_hash``; stripping the
    links makes the hash independent of any re-serialization of the stored
    event object.
    """
    stripped = {key: value for key, value in event.items() if key not in HASH_FIELDS}
    return json.dumps(
        stripped, sort_keys=True, separators=(",", ":"), ensure_ascii=False
    ).encode("utf-8")


def event_hash(prev_hash: str, event: dict) -> str:
    """SHA-256 hex of ``prev_hash`` ASCII bytes followed by the canonical event."""
    return hashlib.sha256(prev_hash.encode("ascii") + canonical_event(event)).hexdigest()


def link_events(events: list[dict]) -> list[dict]:
    """Return copies of ``events`` with dense ids and fresh hash links.

    Event ids are renumbered 1..N; the first event gets the all-zero
    ``prev_hash`` and every later event links to its predecessor. Does not
    mutate the input.
    """
    linked: list[dict] = []
    prev_hash = ZERO_HASH
    for index, event in enumerate(events):
        linked_event = dict(event)
        linked_event["event_id"] = index + 1
        linked_event["prev_hash"] = prev_hash
        linked_event["event_hash"] = event_hash(prev_hash, linked_event)
        linked.append(linked_event)
        prev_hash = linked_event["event_hash"]
    return linked


def make_checkpoint(events: list[dict]) -> dict:
    """``{"event_id", "event_hash"}`` pinning the last event (or the zero root)."""
    if events:
        return {
            "event_id": len(events),
            "event_hash": events[-1]["event_hash"],
        }
    return {"event_id": 0, "event_hash": ZERO_HASH}


# Fields of a page's checkpoint authentication envelope.
AUTH_FIELDS = ("key_version", "signature")


def checkpoint_auth_object(
    genesis_hash: str, checkpoint: dict, key_version: int
) -> dict:
    """The exact JSON object covered by a checkpoint authentication signature.

    ``{"genesis_hash", "checkpoint": {"event_id", "event_hash"},
    "key_version"}`` — the genesis anchor pins the deployment, the checkpoint
    pins the audit log head and the key version selects the verifying public
    key.
    """
    return {
        "genesis_hash": genesis_hash,
        "checkpoint": {
            "event_id": checkpoint["event_id"],
            "event_hash": checkpoint["event_hash"],
        },
        "key_version": key_version,
    }


def checkpoint_auth_bytes(auth_object: dict) -> bytes:
    """Sorted-key compact UTF-8 JSON of a checkpoint authentication object."""
    return json.dumps(
        auth_object, sort_keys=True, separators=(",", ":"), ensure_ascii=False
    ).encode("utf-8")


def sign_checkpoint_auth(
    private_key_hex: str, genesis_hash: str, checkpoint: dict, key_version: int
) -> str:
    """Ed25519-sign SHA-256 of the canonical checkpoint authentication object.

    Returns the 128-hex signature, or None when the private key is malformed.
    """
    auth_object = checkpoint_auth_object(genesis_hash, checkpoint, key_version)
    digest = hashlib.sha256(checkpoint_auth_bytes(auth_object)).digest()
    return crypto.sign_message(private_key_hex, digest)


def verify_checkpoint_auth(
    public_key_hex: str,
    genesis_hash: str,
    checkpoint: dict,
    key_version: int,
    signature_hex: str,
) -> bool:
    """Verify one checkpoint authentication signature. Never raises."""
    auth_object = checkpoint_auth_object(genesis_hash, checkpoint, key_version)
    digest = hashlib.sha256(checkpoint_auth_bytes(auth_object)).digest()
    return crypto.verify_signature(public_key_hex, digest, signature_hex)


def validate_event_chain(events: object) -> None:
    """Strictly validate a persisted event list's dense ids and hash links.

    ``event_id`` values must be exactly 1..N; each ``prev_hash`` must equal the
    previous event's ``event_hash`` (all zeroes for the first event) and every
    ``event_hash`` must recompute from the event with both hash fields removed.
    Raises AuditChainError on the first defect.
    """
    if not isinstance(events, list):
        raise AuditChainError("'audit_events' must be a list")
    prev_hash = ZERO_HASH
    for index, event in enumerate(events):
        event_id = index + 1
        if not isinstance(event, dict):
            raise AuditChainError(f"audit event {event_id} must be an object")
        if not _is_plain_int(event.get("event_id")) or event["event_id"] != event_id:
            raise AuditChainError(
                f"audit event at position {index} has event_id "
                f"{event.get('event_id')!r}, expected {event_id}"
            )
        stored_prev = event.get("prev_hash")
        if not crypto.is_hex64(stored_prev) or stored_prev != prev_hash:
            raise AuditChainError(
                f"audit event {event_id} has a mismatched prev_hash"
            )
        stored_hash = event.get("event_hash")
        if not crypto.is_hex64(stored_hash):
            raise AuditChainError(
                f"audit event {event_id} has an invalid event_hash"
            )
        if event_hash(prev_hash, event) != stored_hash:
            raise AuditChainError(
                f"audit event {event_id} has a mismatched event_hash"
            )
        prev_hash = stored_hash


def validate_checkpoint(checkpoint: object, events: list[dict]) -> None:
    """Validate an ``audit_checkpoint`` against the recovered event list.

    It must be ``{"event_id": N, "event_hash": H}`` with N the (non-negative)
    number of events and H the last event's hash, or the all-zero root when the
    log is empty. Raises AuditChainError on any defect.
    """
    if not isinstance(checkpoint, dict):
        raise AuditChainError("'audit_checkpoint' must be an object")
    event_id = checkpoint.get("event_id")
    event_hash_value = checkpoint.get("event_hash")
    if not _is_plain_int(event_id) or event_id < 0:
        raise AuditChainError("audit_checkpoint.event_id must be a non-negative integer")
    if not crypto.is_hex64(event_hash_value):
        raise AuditChainError("audit_checkpoint.event_hash must be 64 lowercase hex chars")
    expected = make_checkpoint(events)
    if event_id != expected["event_id"]:
        raise AuditChainError(
            f"audit_checkpoint.event_id is {event_id}, log ends at "
            f"{expected['event_id']}"
        )
    if event_hash_value != expected["event_hash"]:
        raise AuditChainError("audit_checkpoint.event_hash does not match the log head")


def verify_export(document: object, trust: object = None) -> dict:
    """Offline-verify one audit export page or an ordered list of pages.

    A page has the server shape
    ``{items, total, next_cursor, anchor_hash, checkpoint}``. Every page
    must pin the identical checkpoint, each page anchor must equal the
    running predecessor hash, item event ids must be dense and consecutive
    across pages, every ``prev_hash``/``event_hash`` pair must recompute,
    pagination counters must be self-consistent and the last page's tail
    must equal that shared checkpoint.

    When ``trust`` is None (the default) no authentication is attempted and
    the behaviour is unchanged. When a trust document is supplied it must
    carry ``genesis_hash`` and a version-ascending ``audit_signers`` list
    (``{version, public_key, activated_event_id}``); every page must then
    carry the same ``checkpoint_auth`` envelope
    (``{key_version, signature}``) binding the same checkpoint, the key
    version must be known and activated at or before the checkpoint, and the
    Ed25519 signature over
    ``SHA256(sorted-compact UTF-8 JSON of {genesis_hash, checkpoint,
    key_version})`` must verify against that version's public key.

    Returns ``{"ok": True, "checkpoint": {...}}`` or
    ``{"ok": False, "error": "input" | "integrity" | "auth"}``. Never raises
    for malformed input.
    """
    try:
        pages = _coerce_pages(document)
        checkpoint = _verify_pages(pages)
        if trust is not None:
            _verify_checkpoint_auth(pages, checkpoint, trust)
    except _VerifyError as failure:
        return {"ok": False, "error": failure.category}
    except Exception:
        # Defensive: structurally unforeseeable inputs report rather than crash.
        return {"ok": False, "error": ERR_INPUT}
    return {"ok": True, "checkpoint": checkpoint}


def _coerce_pages(document: object) -> list[dict]:
    """Normalize a single page object / list of pages, validating basic shape."""
    if isinstance(document, dict):
        pages = [document]
    elif isinstance(document, list) and (
        not document or all(isinstance(page, dict) for page in document)
    ):
        pages = document
    else:
        raise _VerifyError(ERR_INPUT)
    if not pages:
        raise _VerifyError(ERR_INPUT)
    return pages


def _parse_page_shape(page: object) -> dict:
    """Validate a page's structural fields; returns the dict on success."""
    if not isinstance(page, dict):
        raise _VerifyError(ERR_INPUT)
    for field in ("items", "total", "next_cursor", "anchor_hash", "checkpoint"):
        if field not in page:
            raise _VerifyError(ERR_INPUT)
    items = page["items"]
    total = page["total"]
    next_cursor = page["next_cursor"]
    anchor_hash = page["anchor_hash"]
    checkpoint = page["checkpoint"]
    if not isinstance(items, list):
        raise _VerifyError(ERR_INPUT)
    if not _is_plain_int(total) or total < 0:
        raise _VerifyError(ERR_INPUT)
    if next_cursor is not None and (not _is_plain_int(next_cursor) or next_cursor < 0):
        raise _VerifyError(ERR_INPUT)
    if not crypto.is_hex64(anchor_hash):
        raise _VerifyError(ERR_INPUT)
    if not isinstance(checkpoint, dict):
        raise _VerifyError(ERR_INPUT)
    checkpoint_id = checkpoint.get("event_id")
    checkpoint_hash = checkpoint.get("event_hash")
    if not _is_plain_int(checkpoint_id) or checkpoint_id < 0:
        raise _VerifyError(ERR_INPUT)
    if not crypto.is_hex64(checkpoint_hash):
        raise _VerifyError(ERR_INPUT)
    return page


def _verify_pages(pages: list[dict]) -> dict:
    """Walk every page in order; return the shared checkpoint on success."""
    running_id = 0
    running_hash = ZERO_HASH
    first_checkpoint: dict | None = None
    for page in pages:
        page = _parse_page_shape(page)
        items = page["items"]
        total = page["total"]
        next_cursor = page["next_cursor"]
        checkpoint = page["checkpoint"]

        # Every page of one export pins the identical checkpoint; a replaced
        # or regressed checkpoint on any page breaks the export as a whole.
        if first_checkpoint is None:
            first_checkpoint = checkpoint
        elif checkpoint != first_checkpoint:
            raise _VerifyError(ERR_INTEGRITY)
        # The export is unfiltered, so a page's total is the log length its
        # checkpoint was taken over.
        if checkpoint["event_id"] != total:
            raise _VerifyError(ERR_INTEGRITY)
        # This page begins exactly where verification currently stands: the
        # declared anchor is the predecessor hash of its first item (or of the
        # cursor position for an empty page).
        if page["anchor_hash"] != running_hash:
            raise _VerifyError(ERR_INTEGRITY)

        for item in items:
            if not isinstance(item, dict):
                raise _VerifyError(ERR_INPUT)
            event_id = item.get("event_id")
            prev_hash = item.get("prev_hash")
            stored_hash = item.get("event_hash")
            if not _is_plain_int(event_id):
                raise _VerifyError(ERR_INPUT)
            if not crypto.is_hex64(prev_hash) or not crypto.is_hex64(stored_hash):
                raise _VerifyError(ERR_INPUT)
            if event_id != running_id + 1:
                raise _VerifyError(ERR_INTEGRITY)
            if prev_hash != running_hash:
                raise _VerifyError(ERR_INTEGRITY)
            if event_hash(running_hash, item) != stored_hash:
                raise _VerifyError(ERR_INTEGRITY)
            running_id = event_id
            running_hash = stored_hash

        # Pagination self-consistency: a non-null next_cursor continues exactly
        # after this page and stays below total; a server page with limit >= 1
        # is therefore non-empty whenever it is not the last page. A null
        # next_cursor ends exactly at the total.
        if next_cursor is None:
            if running_id != total:
                raise _VerifyError(ERR_INTEGRITY)
        else:
            if not items or next_cursor != running_id or next_cursor >= total:
                raise _VerifyError(ERR_INTEGRITY)

    # The final page must end exactly on the checkpoint every page pinned.
    assert first_checkpoint is not None
    if (
        running_id != first_checkpoint["event_id"]
        or running_hash != first_checkpoint["event_hash"]
    ):
        raise _VerifyError(ERR_INTEGRITY)
    return dict(first_checkpoint)


def _parse_trust_signers(trust: object) -> tuple[str, dict[int, dict]]:
    """Strictly parse a trust document's genesis anchor and audit signers.

    Returns ``(genesis_hash, {version: {public_key, activated_event_id}})``.
    Versions must be dense and ascending starting at 1, the first
    ``activated_event_id`` must be 0 and later activation ids must be strictly
    ascending. Any defect is an input error.
    """
    if not isinstance(trust, dict):
        raise _VerifyError(ERR_INPUT)
    genesis_hash = trust.get("genesis_hash")
    if not crypto.is_hex64(genesis_hash):
        raise _VerifyError(ERR_INPUT)
    raw_signers = trust.get("audit_signers")
    if not isinstance(raw_signers, list) or not raw_signers:
        raise _VerifyError(ERR_INPUT)
    signers: dict[int, dict] = {}
    previous_activated: int | None = None
    for position, entry in enumerate(raw_signers):
        if not isinstance(entry, dict):
            raise _VerifyError(ERR_INPUT)
        version = entry.get("version")
        public_key = entry.get("public_key")
        activated = entry.get("activated_event_id")
        if not _is_plain_int(version) or version != position + 1:
            raise _VerifyError(ERR_INPUT)
        if not crypto.is_hex64(public_key):
            raise _VerifyError(ERR_INPUT)
        if not _is_plain_int(activated) or activated < 0:
            raise _VerifyError(ERR_INPUT)
        if position == 0:
            if activated != 0:
                raise _VerifyError(ERR_INPUT)
        elif activated <= previous_activated:
            # A gap in versions is already rejected above; an activation id
            # that retreats (or stands still) is likewise a malformed list.
            raise _VerifyError(ERR_INPUT)
        previous_activated = activated
        signers[version] = {
            "public_key": public_key,
            "activated_event_id": activated,
        }
    return genesis_hash, signers


def _verify_checkpoint_auth(
    pages: list[dict], checkpoint: dict, trust: object
) -> None:
    """Verify the Ed25519 checkpoint authentication carried by every page.

    Every page must carry the same ``checkpoint_auth`` envelope
    (``{key_version, signature}``) and pin the same checkpoint; the key
    version must identify a signer already activated at or before the
    checkpoint and the signature must verify over
    ``SHA256(sorted-compact UTF-8 JSON of {genesis_hash, checkpoint,
    key_version})`` under the trust document's anchor. Structural defects are
    input errors; missing, unknown-version, cross-page-inconsistent or
    cryptographically invalid authentication is an auth error; a page whose
    checkpoint differs from the verified head is an integrity error.
    """
    genesis_hash, signers = _parse_trust_signers(trust)
    envelopes: list[object] = []
    for page in pages:
        if page.get("checkpoint") != checkpoint:
            # Two pages of one export must pin the same log head.
            raise _VerifyError(ERR_INTEGRITY)
        envelope = page.get("checkpoint_auth")
        if envelope is None:
            raise _VerifyError(ERR_AUTH)
        if not isinstance(envelope, dict):
            raise _VerifyError(ERR_INPUT)
        key_version = envelope.get("key_version")
        signature = envelope.get("signature")
        if not _is_plain_int(key_version) or key_version < 1:
            raise _VerifyError(ERR_INPUT)
        if not isinstance(signature, str) or not crypto.is_hex128(signature):
            raise _VerifyError(ERR_INPUT)
        envelopes.append({"key_version": key_version, "signature": signature})

    first = envelopes[0]
    for envelope in envelopes[1:]:
        if envelope != first:
            raise _VerifyError(ERR_AUTH)

    signer = signers.get(first["key_version"])
    if signer is None:
        raise _VerifyError(ERR_AUTH)
    # A trust document may not describe signer activations that lie beyond the
    # checkpoint head it is meant to authenticate. The *selected* key's own
    # activation beyond the head is reported as auth (an unactivated key
    # version, matching the signed-envelope failure category); any other
    # history entry beyond the head makes the document itself inconsistent
    # with the verified checkpoint and is an input error.
    for other_version, entry in signers.items():
        if other_version == first["key_version"]:
            continue
        if entry["activated_event_id"] > checkpoint["event_id"]:
            raise _VerifyError(ERR_INPUT)
    # A signer can only authenticate a checkpoint taken at or after the event
    # that activated its key.
    if checkpoint["event_id"] < signer["activated_event_id"]:
        raise _VerifyError(ERR_AUTH)
    if not verify_checkpoint_auth(
        signer["public_key"],
        genesis_hash,
        checkpoint,
        first["key_version"],
        first["signature"],
    ):
        raise _VerifyError(ERR_AUTH)

def _allowlist_entry(source: str, expires_at: int) -> dict:
    """Public shape of one keyless allowlist entry."""
    return {"source": source, "expires_at": expires_at}

def add_allowlist_entry(self, payload: object) -> tuple[int, dict]:
    """POST /v1/trust/allowlist — add a keyless source for offline verify.

    The body carries ``source`` (a non-empty string) and ``expires_at`` (a
    plain, non-boolean Unix-seconds integer); anything malformed is 400. A
    new entry is persisted together with its ``allowlist_added`` audit
    event in one atomic write and returns 201 with
    ``{source, expires_at}``. Re-posting the exact same content is
    idempotent (200, no new event, no write); the same source with a
    different expiry conflicts 409 (remove it first).

    The allowlist is keyless and offline-only: it never creates a trust
    source and never authorizes POST /v1/forks/sync, and expired entries
    are retained verbatim (an expired entry is still an entry, so a
    same-content retry stays 200 and a changed-content retry stays 409).
    """
    if not isinstance(payload, dict):
        return 400, {"error": "request body must be a JSON object"}
    for field in ("source", "expires_at"):
        if field not in payload:
            return 400, {"error": f"missing field: {field}"}
    source = payload["source"]
    expires_at = payload["expires_at"]
    if not isinstance(source, str) or not source:
        return 400, {"error": "field 'source' must be a non-empty string"}
    # bool is a subclass of int: reject it and every other non-int type.
    if isinstance(expires_at, bool) or not isinstance(expires_at, int):
        return 400, {"error": "field 'expires_at' must be a Unix-seconds integer"}
    with self.store.lock:
        existing = self.store.allowlist.get(source)
        if existing is not None:
            if existing == expires_at:
                # Idempotent re-add: the stored entry is reported
                # unchanged, with no new audit event and no new write.
                return 200, self._allowlist_entry(source, existing)
            return 409, {"error": "allowlist entry already exists with different content"}
        self.store.allowlist[source] = expires_at
        self.store.append_audit_event(
            EVENT_ALLOWLIST_ADDED,
            {"source": source, "expires_at": expires_at},
        )
        try:
            self.store.save()
        except BaseException:
            # Undo the entry and its event together so a failed write
            # never leaves one without the other.
            self.store.allowlist.pop(source, None)
            self.store.truncate_audit_events(1)
            raise
        return 201, self._allowlist_entry(source, expires_at)

def remove_allowlist_entry(self, source: object) -> tuple[int, dict]:
    """DELETE /v1/trust/allowlist/{source} — remove a keyless entry.

    An unknown source (including the empty path segment) returns 404. A
    known entry is deleted and its ``allowlist_removed`` event (carrying
    the source and the removed entry's ``expires_at``) is persisted in the
    same atomic write; a failed write restores both. Returns
    ``{source, removed: true}`` on success. Removing an allowlist entry
    never touches a same-named entry of the persistent trust registry.
    """
    if not isinstance(source, str) or not source:
        return 404, {"error": "unknown allowlist entry"}
    with self.store.lock:
        existing = self.store.allowlist.get(source)
        if existing is None:
            return 404, {"error": "unknown allowlist entry"}
        del self.store.allowlist[source]
        self.store.append_audit_event(
            EVENT_ALLOWLIST_REMOVED,
            {"source": source, "expires_at": existing},
        )
        try:
            self.store.save()
        except BaseException:
            # Restore the entry and drop its event together.
            self.store.allowlist[source] = existing
            self.store.truncate_audit_events(1)
            raise
        return 200, {"source": source, "removed": True}

# -- audit log ------------------------------------------------------------

AUDIT_DEFAULT_LIMIT = 50
AUDIT_MAX_LIMIT = 200

def rotate_audit_signer(self, payload: object) -> tuple[int, dict]:
    """POST /v1/audit/signer/rotate — install a new Ed25519 checkpoint key.

    The body carries ``private_key`` (64 lowercase hex characters — the
    Ed25519 seed) and ``expected_version`` (the current key version).
    Malformed input returns 400 and a stale ``expected_version`` returns
    409. On success the new key version is derived from the seed, an
    ``audit_signer_rotated`` event records the new version and public key,
    and the key, the event and the refreshed checkpoint are persisted in
    one atomic write (200), returning ``{"version", "public_key"}``. Old
    public keys are retained in the signer history so historical
    checkpoints stay verifiable.
    """
    if not isinstance(payload, dict):
        return 400, {"error": "request body must be a JSON object"}
    for field in ("private_key", "expected_version"):
        if field not in payload:
            return 400, {"error": f"missing field: {field}"}
    private_key = payload["private_key"]
    expected_version = payload["expected_version"]
    if not crypto.is_hex64(private_key):
        return 400, {
            "error": "field 'private_key' must be 64 lowercase hex characters"
        }
    public_key = crypto.derive_public_key(private_key)
    if public_key is None:
        return 400, {
            "error": "field 'private_key' must be 64 lowercase hex characters"
        }
    if (
        isinstance(expected_version, bool)
        or not isinstance(expected_version, int)
        or expected_version < 1
    ):
        return 400, {"error": "field 'expected_version' must be a positive integer"}
    with self.store.lock:
        current = self.store.audit_signer
        if current is None:
            # load() mints/migrates a key for every node, so a live store
            # always has a current signer.
            return 409, {"error": "audit signer is not initialized"}
        if current["version"] != expected_version:
            return 409, {
                "error": "expected_version does not match the current signer version"
            }
        new_version = current["version"] + 1
        old_signer = dict(current)
        history_length = len(self.store.audit_signer_history)
        event = self.store.append_audit_event(
            EVENT_AUDIT_SIGNER_ROTATED,
            {"version": new_version, "public_key": public_key},
        )
        new_signer = {
            "version": new_version,
            "private_key": private_key,
            "public_key": public_key,
            "activated_event_id": event["event_id"],
        }
        self.store.audit_signer = new_signer
        self.store.audit_signer_history.append(
            {
                "version": new_version,
                "public_key": public_key,
                "activated_event_id": event["event_id"],
            }
        )
        try:
            self.store.save()
        except BaseException:
            # Roll the key, the history entry and its audit event back
            # together so a failed write never leaves a rotated key
            # without its event.
            self.store.audit_signer = old_signer
            del self.store.audit_signer_history[history_length:]
            self.store.truncate_audit_events(1)
            raise
        return 200, {"version": new_version, "public_key": public_key}

def list_audit_events(self, params: dict) -> tuple[int, dict]:
    """GET /v1/audit/events — paginated append-only audit log.

    Filters ``source`` and ``kind`` are AND-combined; ``limit`` defaults
    to 50 and must be 1-200, ``cursor`` defaults to 0. Numeric values
    must be plain decimals without leading zeros. Events are ordered by
    their ascending ``event_id``; ``cursor == total`` returns an empty
    page, ``cursor > total`` returns 400.
    """
    source = params.get("source")
    if source is not None and (not isinstance(source, str) or not source):
        return 400, {"error": "source must be a non-empty string"}
    kind = params.get("kind")
    if kind is not None and (not isinstance(kind, str) or not kind):
        return 400, {"error": "kind must be a non-empty string"}
    limit = self.AUDIT_DEFAULT_LIMIT
    if params.get("limit") is not None:
        parsed = _parse_decimal(params["limit"])
        if parsed is None or not 1 <= parsed <= self.AUDIT_MAX_LIMIT:
            return 400, {"error": "limit must be a decimal between 1 and 200"}
        limit = parsed
    cursor = 0
    if params.get("cursor") is not None:
        parsed = _parse_decimal(params["cursor"])
        if parsed is None:
            return 400, {"error": "cursor must be a non-negative decimal"}
        cursor = parsed

    with self.store.lock:
        # Sweep expired syncs first so their expiry events are visible on
        # the same page that observes the removal.
        self._prune_expired_syncs()
        items = [
            dict(event)
            for event in self.store.audit_events
            if (source is None or event.get("source") == source)
            and (kind is None or event.get("kind") == kind)
        ]
    # Events are stored in ascending event_id order; filtering preserves it.
    total = len(items)
    if cursor > total:
        return 400, {"error": "cursor is beyond the result set"}
    page = items[cursor : cursor + limit]
    next_cursor = cursor + limit if cursor + limit < total else None
    return 200, {"items": page, "total": total, "next_cursor": next_cursor}

