# -- node-managed checkpoint history -------------------------------------

HISTORY_TRUST_UPDATE_FIELDS = ("root_seed", "at", "key", "status")
HISTORY_EXPORT_FIELDS = ("key", "after", "limit")

# The light_client failure categories of these two operations are exactly
# input/auth/state/io; map them onto the HTTP status contract.
_HISTORY_STATUS = {
    "input": 400,
    "auth": 403,
    "state": 409,
    "io": 500,
}

@staticmethod
def _history_failure(result: dict) -> tuple[int, dict]:
    category = result.get("error", "io")
    return (
        LedgerService._HISTORY_STATUS.get(category, 500),
        {"ok": False, "error": category},
    )

def _history_locks(self):
    """Context stack for the managed files' per-path locks.

    Acquired in the same order ``export_history`` uses (checkpoint pair
    first, signer log second) so, together with the store lock held by
    every caller, the trust log, the history files and the audit
    event/checkpoint/generation snapshot form one serialized transaction.
    """
    from . import light_client

    return (
        light_client._checkpoint_lock(self.history_path),
        light_client._checkpoint_lock(self.history_trust_path),
    )

def _history_heads(self) -> tuple[str | None, str | None]:
    """Current (trust_head, history_head), null for a not-yet-created file."""
    from . import light_client

    inspection = light_client.inspect_history_files(
        self.history_path, self.history_trust_path
    )
    if not inspection.get("ok"):
        # The endpoint handlers re-verify strictly first; a defect found
        # here is an internal failure to read files we just handled.
        raise OSError(
            inspection.get("path"),
            f"managed history file unreadable: {inspection.get('error')}",
        )
    return inspection["trust_head"], inspection["history_head"]

def _append_history_access_and_save(
    self,
    action: str,
    trust_head: str | None,
    history_head: str | None,
    restore: tuple | None = None,
) -> None:
    """Append the history_access event and persist the snapshot atomically.

    On a save failure the in-memory event is dropped and, when given,
    ``restore`` is a list of ``(path, original_bytes)`` pairs restored
    best-effort; the original OSError is re-raised so the caller answers
    500/io.
    """
    self.store.append_audit_event(
        EVENT_HISTORY_ACCESS,
        {
            "action": action,
            "trust_head": trust_head,
            "history_head": history_head,
        },
    )
    try:
        self.store.save()
    except BaseException:
        self.store.truncate_audit_events(1)
        if restore is not None:
            from . import light_client

            for path, original in restore:
                light_client.restore_file_bytes(path, original)
        raise

