    """GET /v1/history/trust — strictly read the durable signer log.

    Returns the ``{root, records, head}`` document in its contract key
    order. A read is audited with a ``read`` history_access event and the
    event, checkpoint and generation are persisted before responding. A
    missing log is ``io`` (500), a corrupt log ``state`` (409).
    """
    if not self.history_enabled:
        return 404, {"ok": False, "error": "not found"}
    from . import light_client

    with self.store.lock:
        lock_pair, trust_lock = self._history_locks()
        with lock_pair, trust_lock:
            result = light_client.history_trust(self.history_trust_path)
            if result.get("ok") is False:
                return self._history_failure(result)
